//! A module providing merge sort implementations in Rust.

/// Sorts a slice using the merge sort algorithm and returns a new sorted `Vec`.
///
/// # Complexity
///
/// - **Time:** O(n log n) in all cases (best, average, worst).
/// - **Space:** O(n) auxiliary space for the temporary arrays used during merging.
///
/// # Arguments
///
/// * `v` - A slice of elements that implement `Ord` and `Clone`.
///
/// # Returns
///
/// A new `Vec<T>` containing the sorted elements.
///
/// # Examples
///
/// ```
/// use my_module::merge_sort;
///
/// let v = vec![3, 1, 4, 1, 5, 9, 2, 6];
/// let sorted = merge_sort(&v);
/// assert_eq!(sorted, vec![1, 1, 2, 3, 4, 5, 6, 9]);
/// ```
pub fn merge_sort<T: Ord + Clone>(v: &[T]) -> Vec<T> {
    if v.len() <= 1 {
        return v.to_vec();
    }

    let mid = v.len() / 2;
    let left = merge_sort(&v[..mid]);
    let right = merge_sort(&v[mid..]);

    merge(&left, &right)
}

/// Merges two sorted slices into a single sorted `Vec`.
///
/// # Complexity
///
/// - **Time:** O(n + m) where n and m are the lengths of the two input slices.
/// - **Space:** O(n + m) for the output vector.
fn merge<T: Ord + Clone>(left: &[T], right: &[T]) -> Vec<T>

